// Parity test: the browser engine (Pyodide, same pinned version and
// packages as docs/index.html) against the native CPython engine, on
// the same synthetic motion-blurred fixture the pytest suite uses
// (truth: motion, length 15, angle 30, generated by tests/conftest.py).
//
// Run:  npm install && node parity.mjs
// Exits nonzero if any assertion fails. Prints a side by side table.

import { execFileSync } from "node:child_process";
import { readFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { loadPyodide } from "pyodide";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..");
const PYODIDE_VERSION = "0.29.5";
const LENGTH_TOL = 4.0;   // same tolerances as the v0.1.0 test suite
const ANGLE_TOL = 10.0;
const IMPROVE_MIN = 1.30;

let failures = 0;
function check(label, ok, detail) {
  console.log((ok ? "PASS" : "FAIL") + "  " + label + (detail ? "  (" + detail + ")" : ""));
  if (!ok) failures += 1;
}
function angleDiff(a, b) {
  const d = Math.abs(((a - b) % 180 + 180) % 180);
  return Math.min(d, 180 - d);
}

// ---------------------------------------------------------------- native
console.log("== native (CPython, repo .venv) ==");
const nativeJson = execFileSync(
  join(ROOT, ".venv", "bin", "python"),
  [join(HERE, "native_run.py")],
  { encoding: "utf8", timeout: 600000 });
const native = JSON.parse(nativeJson.trim().split("\n").pop());
console.log(JSON.stringify(native, null, 2));

// ---------------------------------------------------------------- pyodide
console.log("== pyodide " + PYODIDE_VERSION + " (browser engine) ==");
console.time("pyodide load + packages");
const pyodide = await loadPyodide();
await pyodide.loadPackage(["numpy", "scipy", "opencv-python", "scikit-image"]);
console.timeEnd("pyodide load + packages");

// Load the repo's own deblur package, the same files the page fetches.
pyodide.FS.mkdir("deblur");
for (const name of readdirSync(join(ROOT, "deblur"))) {
  if (name.endsWith(".py")) {
    pyodide.FS.writeFile("deblur/" + name, readFileSync(join(ROOT, "deblur", name), "utf8"));
  }
}
// The fixture generator, taken from tests/conftest.py itself. The only
// edits are dropping its pytest import and fixture decorator, which
// the generator functions do not use.
let conftest = readFileSync(join(ROOT, "tests", "conftest.py"), "utf8");
conftest = conftest
  .replace(/^import pytest$/m, "")
  .replace(/^@pytest\.fixture.*$/m, "");
pyodide.FS.writeFile("conftest.py", conftest);

const wasmJson = pyodide.runPython(`
import json
from conftest import make_gt, to_bgr
from deblur.psf import apply_blur, motion_psf
from deblur.pipeline import enhance_image
from deblur.browser import enhance_image_browser
from deblur.presets import Settings

blurred = apply_blur(make_gt(), motion_psf(15, 30))
img = to_bgr(blurred)
settings = Settings(blur_type="auto", upscale=None)

def summarize(rep):
    return {"blur_type": rep.blur_type, "psf_params": rep.psf_params,
            "input_score": rep.input_score, "output_score": rep.output_score,
            "ratio": rep.output_score / rep.input_score}

_, full = enhance_image(img, settings)
_, staged, info = enhance_image_browser(img, settings)
json.dumps({"full": summarize(full), "staged": summarize(staged),
            "staged_info": {"estimated": info["estimated"],
                            "psf_params": info["psf_params"],
                            "scale_factor": info["scale_factor"],
                            "notes": info["notes"]}})
`);
const wasm = JSON.parse(wasmJson);
console.log(JSON.stringify(wasm, null, 2));

// ---------------------------------------------------------------- asserts
for (const side of ["full", "staged"]) {
  for (const [name, res] of [["native", native[side]], ["pyodide", wasm[side]]]) {
    check(name + " " + side + ": family is motion", res.blur_type === "motion", res.blur_type);
    check(name + " " + side + ": length within " + LENGTH_TOL + " of 15",
      Math.abs(res.psf_params.length - 15) <= LENGTH_TOL, "length=" + res.psf_params.length);
    check(name + " " + side + ": angle within " + ANGLE_TOL + " of 30",
      angleDiff(res.psf_params.angle, 30) <= ANGLE_TOL, "angle=" + res.psf_params.angle);
    check(name + " " + side + ": output at least " + IMPROVE_MIN + "x sharper than input",
      res.ratio >= IMPROVE_MIN, "ratio=" + res.ratio.toFixed(3));
  }
  const a = native[side], b = wasm[side];
  check("parity " + side + ": pyodide length matches native within " + LENGTH_TOL,
    Math.abs(b.psf_params.length - a.psf_params.length) <= LENGTH_TOL,
    "native=" + a.psf_params.length + " pyodide=" + b.psf_params.length);
  check("parity " + side + ": pyodide angle matches native within " + ANGLE_TOL,
    angleDiff(b.psf_params.angle, a.psf_params.angle) <= ANGLE_TOL,
    "native=" + a.psf_params.angle + " pyodide=" + b.psf_params.angle);
  check("parity " + side + ": sharpening ratio within 25% across engines",
    Math.abs(b.ratio - a.ratio) / a.ratio <= 0.25,
    "native=" + a.ratio.toFixed(3) + " pyodide=" + b.ratio.toFixed(3));
}
check("pyodide staged: estimation ran, scale factor 1.0 at 400 px",
  wasm.staged_info.estimated === true && wasm.staged_info.scale_factor === 1.0,
  JSON.stringify(wasm.staged_info));

console.log("\nside by side (full pipeline):");
console.log("                 native    pyodide");
console.log("length           " + native.full.psf_params.length + "        " + wasm.full.psf_params.length);
console.log("angle            " + native.full.psf_params.angle + "        " + wasm.full.psf_params.angle);
console.log("input score      " + native.full.input_score.toFixed(5) + "   " + wasm.full.input_score.toFixed(5));
console.log("output score     " + native.full.output_score.toFixed(5) + "   " + wasm.full.output_score.toFixed(5));
console.log("ratio            " + native.full.ratio.toFixed(3) + "     " + wasm.full.ratio.toFixed(3));

if (failures) {
  console.error("\n" + failures + " parity check(s) FAILED");
  process.exit(1);
}
console.log("\nall parity checks passed");
